/**
 * The contract `switch-field.tsx` (native) and `switch-field.web.tsx` (DOM) both implement. Its own
 * module because Metro resolves `./switch-field` to `switch-field.web.tsx` on web — the web file
 * would otherwise import itself.
 */
export type SwitchFieldProps = {
  /** The switch's id. On web it is also what the caption's `<label htmlFor>` points at. */
  id: string;
  label: string;
  checked: boolean;
  onCheckedChange: (checked: boolean) => void;
  className?: string | undefined;
  labelClassName?: string | undefined;
};

/** The caption's type, shared so the two halves cannot drift on it. */
export const SWITCH_FIELD_LABEL_CLASS = "text-sm text-muted-foreground";

/**
 * A switch with its caption on one row. `switch-field.web.tsx` is the DOM half and
 * `switch-field-base.ts` holds the contract they share.
 *
 * There is no label/control association off web, so here the caption is a `Pressable` that
 * toggles the switch explicitly — one row, one target. The web half cannot do the same: a
 * `Pressable` there is a `<button>`, and a `<button>` around a `<label htmlFor>` toggles the switch
 * twice per click (once for the button, once for the label's activation) and adds a tab stop with
 * no role. So the web half is a `<label htmlFor>` wrapping the row instead, which is the hit target
 * the browser already gives a labelled control.
 */
import { Pressable, View } from "react-native";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { SWITCH_FIELD_LABEL_CLASS, type SwitchFieldProps } from "@/components/ui/switch-field-base";
import { cn } from "@/lib/utils";

export function SwitchField({
  id,
  label,
  checked,
  onCheckedChange,
  className,
  labelClassName,
}: SwitchFieldProps) {
  return (
    <View className={cn("flex-row items-center gap-2", className)}>
      <Switch id={id} checked={checked} onCheckedChange={onCheckedChange} />
      <Pressable onPress={() => onCheckedChange(!checked)}>
        <Label htmlFor={id} className={cn(SWITCH_FIELD_LABEL_CLASS, labelClassName)}>
          {label}
        </Label>
      </Pressable>
    </View>
  );
}

export type { SwitchFieldProps };

/**
 * The web switch field: one `<label htmlFor>` wrapping the switch and its caption, so the whole row
 * is the switch's hit target and the switch is the row's only tab stop. `switch-field.tsx` is the
 * native counterpart and `switch-field-base.ts` holds the contract they share.
 *
 * It used to be compiled from the native source, whose caption is a `Pressable` that toggles the
 * switch by hand. That compiled to a `<button>` around the `<label htmlFor>`, and a click on the
 * caption then toggled twice — the button's handler, then the label's activation clicking the
 * switch — and so did nothing. It also put a second, role-less tab stop after the switch, and a
 * label inside a button is not valid HTML. The label alone is the whole mechanism here: a click on
 * the switch itself is a click on interactive content, which a label does not re-activate.
 */

import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { SWITCH_FIELD_LABEL_CLASS, type SwitchFieldProps } from "@/components/ui/switch-field-base";
import { cn } from "@/lib/utils";

export function SwitchField({
  id,
  label,
  checked,
  onCheckedChange,
  className,
  labelClassName,
}: SwitchFieldProps) {
  return (
    <Label
      htmlFor={id}
      data-slot="switch-field"
      className={cn("flex cursor-pointer flex-row items-center gap-2", className)}
    >
      <Switch id={id} checked={checked} onCheckedChange={onCheckedChange} />
      <span className={cn(SWITCH_FIELD_LABEL_CLASS, labelClassName)}>{label}</span>
    </Label>
  );
}

export type { SwitchFieldProps };
